def lexicographicallySmallest(S, k):
    n = len(S)
    if n == 0:
        return -1
    if (n & (n - 1)) == 0:
        k = k // 2
    else:
        k = k * 2
    if k >= n or k < 0:
        return -1
    stack = []
    for char in S:
        while k > 0 and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)
    if k > 0:
        stack = stack[:-k]
    return ''.join(stack) if stack else -1
